"""The generated files of the repository and the check that they are current.

Sample events, packet captures, converted queries and the coverage document are
all built from the rules and from detlab.samples and detlab.pcaps. They are
committed so the repository can be read without running anything. A test fails
when a committed file differs from what the code builds.
"""

import os
import tempfile
from pathlib import Path

from detlab import attack, pcaps, samples
from detlab.convert import to_eql
from detlab.rules import ROOT, LabRule, load_rules
from detlab.suricata import SuricataRule, load_suricata_rules

EVENTS_DIR = ROOT / "simulations" / "events"
PCAP_DIR = ROOT / "simulations" / "pcaps"
EQL_DIR = ROOT / "converted" / "eql"
COVERAGE = ROOT / "docs" / "COVERAGE.md"
GENERATED_DIRS = {EVENTS_DIR: ".ndjson", PCAP_DIR: ".pcap", EQL_DIR: ".eql"}


def event_files() -> dict[Path, bytes]:
    attack_events, benign_events = samples.build()
    return {EVENTS_DIR / "attack.ndjson": samples.to_ndjson(attack_events).encode("utf-8"),
            EVENTS_DIR / "benign.ndjson": samples.to_ndjson(benign_events).encode("utf-8")}


def pcap_files() -> dict[Path, bytes]:
    from scapy.utils import wrpcap

    files = {}
    with tempfile.TemporaryDirectory() as scratch:
        for name, (packets, _sids) in pcaps.build().items():
            target = os.path.join(scratch, name + ".pcap")
            wrpcap(target, packets)
            files[PCAP_DIR / (name + ".pcap")] = Path(target).read_bytes()
    return files


def _technique_text(techniques: list[str]) -> str:
    names = attack.reference()["techniques"]
    return ", ".join(f"{technique} {names[technique]['name']}" for technique in techniques)


def eql_files(rules: list[LabRule]) -> dict[Path, bytes]:
    files = {}
    for rule in rules:
        text = (f"// {rule.title}\n"
                f"// Sigma rule: {rule.relative_path} ({rule.rule.id})\n"
                f"// Level: {rule.level}. ATT&CK: {_technique_text(rule.techniques)}\n"
                f"// Generated by `python -m detlab build`. Change the Sigma rule, not this file.\n"
                f"{to_eql(rule)}\n")
        files[EQL_DIR / (rule.key + ".eql")] = text.encode("utf-8")
    return files


def _link(technique: str) -> str:
    return f"[{technique}](https://attack.mitre.org/techniques/{technique.replace('.', '/')}/)"


def coverage_file(rules: list[LabRule], network_rules: list[SuricataRule]) -> dict[Path, bytes]:
    data = attack.reference()
    attack_events, benign_events = samples.build()
    captures = {sid: name for name, (_packets, sids) in pcaps.build().items() for sid in sids}

    def count(events, key):
        return sum(1 for event in events if event["labels"]["lab_rule"] == key)

    by_tactic: dict[str, dict[str, list[str]]] = {tactic: {} for tactic in attack.TACTIC_ORDER}
    for rule in rules:
        for technique in rule.techniques:
            for tactic in rule.tactics:
                if tactic in data["techniques"][technique]["tactics"]:
                    by_tactic[tactic].setdefault(technique, []).append(f"`{rule.key}`")
    for rule in network_rules:
        by_tactic[rule.tactic].setdefault(rule.technique, []).append(f"`sid {rule.sid}`")

    windows = sum(1 for rule in rules if rule.product == "windows")
    linux = sum(1 for rule in rules if rule.product == "linux")
    techniques = {technique for rule in rules for technique in rule.techniques} | {r.technique for r in network_rules}
    covered = [tactic for tactic in attack.TACTIC_ORDER if by_tactic[tactic]]
    lines = [
        "# Detection coverage",
        "",
        "Generated by `python -m detlab build` from the rules in this repository. Do not edit it by hand.",
        "",
        f"The lab holds {len(rules) + len(network_rules)} detections: {len(rules)} Sigma rules ({windows} for "
        f"Windows and {linux} for Linux) and {len(network_rules)} Suricata rules. They map to "
        f"{len(techniques)} techniques in {len(covered)} of the {len(attack.TACTIC_ORDER)} tactics of "
        f"MITRE ATT&CK Enterprise {data['version']}.",
        "",
        "Coverage here means that a rule exists and fires on the lab's own sample of the technique. "
        "It does not mean that every variant of the technique is detected.",
        "",
        "## By tactic",
        "",
        "| Tactic | Technique | Detections |",
        "|---|---|---|",
    ]
    for tactic in attack.TACTIC_ORDER:
        entry = data["tactics"][tactic]
        if not by_tactic[tactic]:
            lines.append(f"| {entry['name']} ({entry['id']}) | none | |")
            continue
        for technique in sorted(by_tactic[tactic]):
            name = data["techniques"][technique]["name"]
            lines.append(f"| {entry['name']} ({entry['id']}) | {_link(technique)} {name} | "
                         f"{'<br>'.join(by_tactic[tactic][technique])} |")
    lines += [
        "",
        "## Sigma rules",
        "",
        "Samples are the events in `simulations/events` that belong to the rule: "
        "events that must fire it and near misses that must not.",
        "",
        "| Rule | Title | Level | Log source | ATT&CK | Attack samples | Benign samples |",
        "|---|---|---|---|---|---|---|",
    ]
    for rule in rules:
        lines.append(f"| [`{rule.key}`](../{rule.relative_path}) | {rule.title} | {rule.level} | "
                     f"{rule.product} {rule.category} | {' '.join(_link(t) for t in rule.techniques)} | "
                     f"{count(attack_events, rule.key)} | {count(benign_events, rule.key)} |")
    lines += [
        "",
        "## Suricata rules",
        "",
        "Each rule has a capture in `simulations/pcaps` that must raise it. "
        "`benign_traffic.pcap` must raise none of them.",
        "",
        "| SID | Rule | Protocol | ATT&CK | Capture |",
        "|---|---|---|---|---|",
    ]
    for rule in network_rules:
        lines.append(f"| {rule.sid} | {rule.msg.replace('DETLAB ', '')} | {rule.protocol} | "
                     f"{_link(rule.technique)} | `{captures.get(rule.sid, 'none')}.pcap` |")
    return {COVERAGE: ("\n".join(lines) + "\n").encode("utf-8")}


def generated_files() -> dict[Path, bytes]:
    rules = load_rules()
    network_rules = load_suricata_rules()
    files: dict[Path, bytes] = {}
    files.update(event_files())
    files.update(pcap_files())
    files.update(eql_files(rules))
    files.update(coverage_file(rules, network_rules))
    return files


def write(files: dict[Path, bytes]) -> list[Path]:
    """Write the files, remove generated files that no longer belong and return what changed."""
    changed = []
    for path, content in files.items():
        if not path.exists() or path.read_bytes() != content:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)
            changed.append(path)
    for path in _orphans(files):
        path.unlink()
        changed.append(path)
    return changed


def _orphans(files: dict[Path, bytes]) -> list[Path]:
    return [path for directory, suffix in GENERATED_DIRS.items() if directory.is_dir()
            for path in sorted(directory.glob("*" + suffix)) if path not in files]


def stale(files: dict[Path, bytes]) -> list[str]:
    """Generated files that are missing, out of date or left over. Empty when everything is current."""
    problems = []
    for path, content in files.items():
        relative = path.relative_to(ROOT).as_posix()
        if not path.exists():
            problems.append(f"{relative}: missing")
        elif path.read_bytes() != content:
            problems.append(f"{relative}: out of date")
    problems += [f"{path.relative_to(ROOT).as_posix()}: no longer generated" for path in _orphans(files)]
    return problems
